21	// The native kustomize gate (DEVDESK-771). Go never applies a proxy to the
22	// loopback, so offlineEnviron cannot stop a native kustomize that reads an
23	// overlay naming http://127.0.0.1:8080/x.yaml from sending a GET to a service of
24	// this machine. The overlay is therefore read first, and kustomize is started
25	// only when every reference in it, and in everything it pulls in, can only name
26	// a path of this repository.
27	//
28	// The gate is a closed whitelist, not a list of what to refuse: a reference is
29	// accepted when localRef says it can only be a local path, the YAML is read the
30	// closed way (no anchor, alias, merge key, explicit tag, duplicate key, key that
31	// is not ASCII, second document), every field of the kustomization is one the
32	// gate knows, and every plugin is a builtin one. What it cannot judge is refused
33	// as such: kustomize is not started either. The fields and the plugin kinds are
34	// the ones of kustomize v5.8.3 (api v0.21.3, types.Kustomization and the
35	// builtinhelpers factories).
36	
37	// gateKind is what the gate says about an overlay.
38	type gateKind int
39	
40	const (
41		// gateOK: every reference is local, kustomize may be started.
42		gateOK gateKind = iota
43		// gateRemote: a reference that is not a path of the repository.
44		gateRemote
45		// gateUnchecked: something the gate cannot judge, or cannot read.
46		gateUnchecked
47	)
48	
49	func (k gateKind) String() string {
50		switch k {
51		case gateOK:
52			return "ok"
53		case gateRemote:
54			return "remote"
55		case gateUnchecked:
56			return "unchecked"
57		}
58		return fmt.Sprintf("gateKind(%d)", int(k))
59	}
60	
61	// gateVerdict is the answer for one overlay. File is relative to the limit, with
62	// forward slashes; Field is the YAML path of the entry, with list indices
63	// (resources[1], patches[0].path); for an inline plugin configuration it is the
64	// field of the kustomization followed by the field of the plugin
65	// (transformers[0].path), for a plugin file the field inside that file. Ref is
66	// what localRef was given.
67	type gateVerdict struct {
68		Kind                     gateKind
69		File, Field, Ref, Reason string
70	}
71	
72	// gateLimits bound what the gate reads of a repository that is not trusted.
73	type gateLimits struct {
74		// Depth is the number of levels of overlay below the first; Visited the
75		// number of distinct kustomizations read.
76		Depth, Visited int
77		// FileBytes is the size of one file; TotalBytes of every file read for one
78		// overlay.
79		FileBytes, TotalBytes int64
80	}
81	
82	// defaultGateLimits keep the gate itself cheap: YAML read into nodes costs about a
83	// hundred times the size of the file in memory, so a megabyte per file and eight
84	// for an overlay bound what a repository that is not trusted can make it spend.
85	var defaultGateLimits = gateLimits{Depth: 16, Visited: 256, FileBytes: 1 << 20, TotalBytes: 8 << 20}
86	
87	// localRef reports whether ref can only name a path of this repository. It
88	// accepts a non-empty string without a control character, without ':' (a scheme,
89	// a port, a drive), '@' (an ssh user) or '?' (a query), that is neither absolute
90	// nor starts with a separator, and whose first segment is not github.com (which
91	// kustomize reads as a git repository even when such a folder exists). reason is
92	// "" when it is local, and says why not otherwise.
93	func localRef(ref string) (ok bool, reason string) {
94		switch {
95		case ref == "":
96			return false, "it is empty"
97		case strings.IndexFunc(ref, unicode.IsControl) >= 0:
98			return false, "it holds a control character"
99		case strings.ContainsAny(ref, ":@?"):
100			return false, "it holds a character that a URL, an address or a drive uses"
101		case strings.HasPrefix(ref, "/") || strings.HasPrefix(ref, `\`) || filepath.IsAbs(ref):
102			return false, "it is an absolute path"
103		}
104		if first, _, _ := strings.Cut(ref, "/"); strings.EqualFold(first, "github.com") {
105			return false, "kustomize reads a name that starts with github.com as a git repository"
106		}
107		return true, ""
108	}
109	
110	// ── Reading a file the closed way ────────────────────────────────────────────
111	
112	// readGateYAML reads one file of an overlay and returns the mapping at the top of
113	// its only document. A reason says why it cannot be judged, and the node is nil.
114	func readGateYAML(file string, maxBytes int64) (*yaml.Node, string) {
115		data, reason := readGateFile(file, maxBytes)
116		if reason != "" {
117			return nil, reason
118		}
119		return parseGateYAML(data)
120	}
121	
122	// readGateFile reads a regular file of at most maxBytes.
123	func readGateFile(file string, maxBytes int64) ([]byte, string) {
124		maxBytes = max(maxBytes, 0)
125		info, err := os.Stat(file)
126		if err != nil {
127			return nil, "it cannot be read (" + errReason(err) + ")"
128		}
129		if !info.Mode().IsRegular() {
130			return nil, "it is not a regular file"
131		}
132		tooBig := fmt.Sprintf("it is larger than %d bytes", maxBytes)
133		if info.Size() > maxBytes {
134			return nil, tooBig
135		}
136		f, err := os.Open(file) //nolint:gosec // a file of the repository being scanned, vetted above
137		if err != nil {
138			return nil, "it cannot be read (" + errReason(err) + ")"
139		}
140		defer func() { _ = f.Close() }()
141		// The size may have changed since the stat: one byte more says it did.
142		data, err := io.ReadAll(io.LimitReader(f, maxBytes+1))
143		if err != nil {
144			return nil, "it cannot be read (" + errReason(err) + ")"
145		}
146		if int64(len(data)) > maxBytes {
147			return nil, tooBig
148		}
149		return data, ""
150	}
151	
152	// errReason is err without the path an os error carries.
153	func errReason(err error) string {
154		var pathErr *fs.PathError
155		if errors.As(err, &pathErr) {
156			return pathErr.Err.Error()
157		}
158		return err.Error()
159	}
160	
161	// reasonNoDocument is the reason for a file with nothing in it but comments.
162	const reasonNoDocument = "it holds no YAML document"
163	
164	// parseGateYAML returns the mapping at the top of the only document of data.
165	func parseGateYAML(data []byte) (*yaml.Node, string) {
166		dec := yaml.NewDecoder(bytes.NewReader(data))
167		var doc yaml.Node
168		if err := dec.Decode(&doc); err != nil {
169			if errors.Is(err, io.EOF) {
170				return nil, reasonNoDocument
171			}
172			return nil, "it is not valid YAML"
173		}
174		var next yaml.Node
175		if err := dec.Decode(&next); !errors.Is(err, io.EOF) {
176			return nil, "it holds more than one YAML document"
177		}
178		if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
179			return nil, "its top level is not a mapping"
180		}
181		top := doc.Content[0]
182		if problem := nodeProblem(top); problem != "" {
183			return nil, "it holds " + problem
184		}
185		return top, ""
186	}
187	
188	// nodeProblem names what makes a node something the gate does not read: kustomize
189	// resolves anchors, aliases and merge keys, applies tags, matches field names
190	// without regard to case (and, for a non-ASCII letter, to Unicode folding) and
191	// keeps the last of two equal keys, so a reading that does not do the same is
192	// not a reading of what kustomize will do.
193	func nodeProblem(n *yaml.Node) string {
194		switch {
195		case n.Kind == yaml.AliasNode:
196			return "an alias"
197		case n.Anchor != "":
198			return "an anchor"
199		case n.Style&yaml.TaggedStyle != 0:
200			return "an explicit tag"
201		}
202		switch n.Kind {
203		case yaml.MappingNode:
204			seen := map[string]bool{}
205			for i := 0; i+1 < len(n.Content); i += 2 {
206				key := n.Content[i]
207				if problem := keyProblem(key, seen); problem != "" {
208					return problem
209				}
210				if problem := nodeProblem(n.Content[i+1]); problem != "" {
211					return problem
212				}
213			}
214		case yaml.SequenceNode:
215			for _, c := range n.Content {
216				if problem := nodeProblem(c); problem != "" {
217					return problem
218				}
219			}
220		}
221		return ""
222	}
223	
224	func keyProblem(key *yaml.Node, seen map[string]bool) string {
225		if problem := nodeProblem(key); problem != "" {
226			return problem
227		}
228		switch {
229		case key.Kind == yaml.ScalarNode && key.Value == "<<":
230			return "a merge key"
231		case key.Kind != yaml.ScalarNode || key.Tag != "!!str":
232			return "a key that is not a string"
233		}
234		for i := 0; i < len(key.Value); i++ {
235			if key.Value[i] >= 0x80 {
236				return "a key that is not ASCII"
237			}
238		}
239		folded := strings.ToLower(key.Value)
240		if seen[folded] {
241			return "a duplicate key"
242		}
243		seen[folded] = true
244		return ""
245	}
246	
247	// ── What each field is ───────────────────────────────────────────────────────
248	
249	type gateRuleKind int
250	
251	const (
252		// gateData: no reference (a name, a label, an inline patch, a literal).
253		gateData gateRuleKind = iota
254		// gateFile: a reference to a file, not followed.
255		gateFile
256		// gateBase: a reference to a file or to a directory with a kustomization,
257		// which is read in turn.
258		gateBase
259		// gateFileSource: a files entry of a generator, `path` or `key=path`.
260		gateFileSource
261		// gatePlugin: a generator, transformer or validator, inline or the path of a
262		// configuration file. A directory is refused: kustomize reads the resources of
263		// its kustomization as plugin configurations, which the gate does not follow.
264		gatePlugin
265		// gatePatch: a strategic merge patch, inline or a path.
266		gatePatch
267		// gateNever: a value that names a program or its arguments: always refused.
268		gateNever
269		gateList
270		gateMap
271	)
272	
273	// gateRule says how the value of a field is judged: a list judges each of its
274	// elements by elem, a mapping each of its entries by fields (an entry it does
275	// not list holds no reference).
276	type gateRule struct {
277		kind   gateRuleKind
278		elem   *gateRule
279		fields map[string]gateRule
280	}
281	
282	func listOf(r gateRule) gateRule { return gateRule{kind: gateList, elem: &r} }
283	
284	func mapOf(fields map[string]gateRule) gateRule { return gateRule{kind: gateMap, fields: fields} }
285	
286	func lookupRule(fields map[string]gateRule, key string) (gateRule, bool) {
287		for name, r := range fields {
288			if strings.EqualFold(name, key) {
289				return r, true
290			}
291		}
292		return gateRule{}, false
293	}
294	
295	var (
296		dataRule       = gateRule{}
297		fileRule       = gateRule{kind: gateFile}
298		baseRule       = gateRule{kind: gateBase}
299		fileSourceRule = gateRule{kind: gateFileSource}
300		pluginRule     = gateRule{kind: gatePlugin}
301		patchRule      = gateRule{kind: gatePatch}
302		neverRule      = gateRule{kind: gateNever}
303	)
304	
305	// pathOnly is a mapping whose `path` holds a reference: a patch, a replacement.
306	var pathOnly = mapOf(map[string]gateRule{"path": fileRule})
307	
308	// kvSources are the fields of a generator of configMaps or secrets that name a
309	// file: a configMapGenerator entry and the configuration of the builtin plugin
310	// hold the same ones.
311	var kvSources = map[string]gateRule{
312		"files": listOf(fileSourceRule),
313		"envs":  listOf(fileRule),
314		"env":   fileRule,
315	}
316	
317	// kustomizationRules lists every top level field of a kustomization of
318	// kustomize v5.8.3. A field that is not here is refused as unknown (kustomize
319	// rejects it too, but the gate does not rely on that).
320	var kustomizationRules = map[string]gateRule{
321		"apiVersion": dataRule, "kind": dataRule, "metadata": dataRule,
322		"namePrefix": dataRule, "nameSuffix": dataRule, "namespace": dataRule,
323		"commonLabels": dataRule, "labels": dataRule, "commonAnnotations": dataRule,
324		"images": dataRule, "imageTags": dataRule, "replicas": dataRule, "vars": dataRule,
325		"sortOptions": dataRule, "generatorOptions": dataRule, "buildMetadata": dataRule,
326	
327		"resources": listOf(baseRule), "bases": listOf(baseRule), "components": listOf(baseRule),
328		"crds": listOf(fileRule), "configurations": listOf(fileRule),
329		"openapi": pathOnly,
330	
331		"patches": listOf(pathOnly), "patchesJson6902": listOf(pathOnly),
332		"patchesStrategicMerge": listOf(patchRule),
333		"replacements":          listOf(pathOnly),
334	
335		"configMapGenerator": listOf(mapOf(kvSources)),
336		"secretGenerator":    listOf(mapOf(kvSources)),
337	
338		"helmGlobals": mapOf(map[string]gateRule{"chartHome": fileRule, "configHome": fileRule}),
339		// A chart name is a reference too: helm pulls what an oci:// name says.
340		"helmCharts": listOf(mapOf(map[string]gateRule{
341			"name": fileRule, "repo": fileRule, "valuesFile": fileRule, "additionalValuesFiles": listOf(fileRule), "chartHome": fileRule,
342		})),
343		"helmChartInflationGenerator": listOf(mapOf(map[string]gateRule{
344			"chartName": fileRule, "chartRepoUrl": fileRule, "chartHome": fileRule, "helmHome": fileRule, "values": fileRule,
345			"helmBin": neverRule, "extraArgs": neverRule,
346		})),
347	
348		"generators": listOf(pluginRule), "transformers": listOf(pluginRule), "validators": listOf(pluginRule),
349	}
350	
351	// builtinPlugins are the kinds of apiVersion builtin that kustomize v5.8.3 loads
352	// (builtinhelpers), with the fields of their configuration that name a file. The
353	// kinds with no such field read nothing from the file system: they take names,
354	// labels, an image, a count or a policy, so they are accepted as they are.
355	var builtinPlugins = map[string]map[string]gateRule{
356		"ConfigMapGenerator": kvSources, "SecretGenerator": kvSources,
357		"PatchTransformer": {"path": fileRule}, "PatchJson6902Transformer": {"path": fileRule},
358		"PatchStrategicMergeTransformer": {"paths": listOf(patchRule)},
359		"ReplacementTransformer":         {"replacements": listOf(pathOnly)},
360		"ValueAddTransformer":            {"targetFilePath": fileRule},
361		"HelmChartInflationGenerator": {
362			"name": fileRule, "chartHome": fileRule, "configHome": fileRule, "repo": fileRule, "valuesFile": fileRule,
363			"additionalValuesFiles": listOf(fileRule),
364		},
365	
366		"AnnotationsTransformer": nil, "LabelTransformer": nil, "NamespaceTransformer": nil,
367		"PrefixTransformer": nil, "SuffixTransformer": nil, "PrefixSuffixTransformer": nil,
368		"ImageTagTransformer": nil, "ReplicaCountTransformer": nil, "HashTransformer": nil,
369		"IAMPolicyGenerator": nil,
370	}
371	
372	// functionAnnotations make kustomize run a program or a container for a plugin.
373	var functionAnnotations = []string{"config.kubernetes.io/function", "config.k8s.io/function"}
374	
375	// kustomizationNames are the file names kustomize recognizes.
376	var kustomizationNames = []string{"kustomization.yaml", "kustomization.yml", "Kustomization"}
377	
378	// ── The walk ─────────────────────────────────────────────────────────────────
379	
380	// gate is one run of vetOverlay.
381	type gate struct {
382		ctx     context.Context //nolint:containedctx // one run of the gate, never stored
383		root    string          // the limit, absolute, symbolic links resolved
384		lim     gateLimits
385		visited map[string]bool // directories entered, by real path
386		count   int             // kustomizations read
387		read    int64           // bytes read
388		bases   []string        // the directories the kustomization being read pulls in
389		limit   string          // what the limit is called in a reason
390		cache   *gateCache
391	}
392	
393	// gateCache remembers, for the whole pass of a scan, the directories whose
394	// kustomization and everything it pulls in were judged local, so that overlays
395	// that share a base read it once. Only a verdict of OK is kept, and only once the
396	// whole overlay is OK: a directory met while a cycle was still open is not known
397	// to be fine before that. A nil cache remembers nothing.
398	type gateCache struct {
399		mu sync.Mutex
400		ok map[string]bool
401	}
402	
403	func (c *gateCache) has(real string) bool {
404		if c == nil {
405			return false
406		}
407		c.mu.Lock()
408		defer c.mu.Unlock()
409		return c.ok[real]
410	}
411	
412	func (c *gateCache) add(dirs map[string]bool) {
413		if c == nil {
414			return
415		}
416		c.mu.Lock()
417		defer c.mu.Unlock()
418		if c.ok == nil {
419			c.ok = map[string]bool{}
420		}
421		for d := range dirs {
422			c.ok[d] = true
423		}
424	}
425	
426	// gateRun is what a caller that asks about many overlays of one scan adds.
427	type gateRun struct {
428		cache *gateCache
429		// limit is how the limit of the paths is called in a reason: "the scanned
430		// folder" or "the repository" (the default).
431		limit string
432	}
433	
434	// gateSite is where a value was read: file is the file it is in (relative to
435	// the limit), dir the directory its references are relative to (the one of the
436	// kustomization, also for a plugin file), depth how far below the first overlay.
437	type gateSite struct {
438		file  string
439		dir   string
440		depth int
441	}
442	
443	func (s gateSite) remote(field, ref, reason string) gateVerdict {
444		return gateVerdict{Kind: gateRemote, File: s.file, Field: field, Ref: ref, Reason: reason}
445	}
446	
447	func (s gateSite) unchecked(field, ref, reason string) gateVerdict {
448		return gateVerdict{Kind: gateUnchecked, File: s.file, Field: field, Ref: ref, Reason: reason}
449	}
450	
451	// vetOverlay reads the overlay directory (absolute) and everything it pulls in,
452	// inside root (absolute; the gate resolves symbolic links itself).
453	func vetOverlay(ctx context.Context, root, overlay string, lim gateLimits) gateVerdict {
454		return vetOverlayIn(ctx, root, overlay, lim, gateRun{})
455	}
456	
457	// vetOverlayIn is vetOverlay for one pass of a scan.
458	func vetOverlayIn(ctx context.Context, root, overlay string, lim gateLimits, run gateRun) gateVerdict {
459		if run.limit == "" {
460			run.limit = "the repository"
461		}
462		unchecked := func(reason string) gateVerdict { return gateVerdict{Kind: gateUnchecked, Reason: reason} }
463		root, err := filepath.Abs(root)
464		if err != nil {
465			return unchecked("the limit of the paths cannot be resolved")
466		}
467		if root, err = filepath.EvalSymlinks(root); err != nil {
468			return unchecked("the limit of the paths cannot be resolved")
469		}
470		if overlay, err = filepath.Abs(overlay); err != nil {
471			return unchecked("the overlay cannot be resolved")
472		}
473		real, err := filepath.EvalSymlinks(overlay)
474		switch {
475		case isMissing(err):
476			return gateVerdict{} // kustomize reports it, and fetches nothing
477		case err != nil:
478			return unchecked("the overlay cannot be resolved")
479		case !within(root, real):
480			return unchecked("the overlay is outside " + run.limit)
481		}
482		g := &gate{ctx: ctx, root: root, lim: lim, visited: map[string]bool{}, limit: run.limit, cache: run.cache}
483		v := g.dir(real, 0)
484		if v.Kind == gateOK {
485			run.cache.add(g.visited)
486		}
487		return v
488	}
489	
490	// within reports whether p is root or below it, lexically.
491	func within(root, p string) bool {
492		rel, err := filepath.Rel(root, p)
493		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
494	}
495	
496	// isMissing reports whether err says a path is not there (or has a file where a
497	// directory should be): nothing for kustomize to load, so nothing to fetch.
498	func isMissing(err error) bool {
499		return err != nil && (errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ENOTDIR))
500	}
501	
502	// rel is p relative to the limit, with forward slashes.
503	func (g *gate) rel(p string) string {
504		r, err := filepath.Rel(g.root, p)
505		if err != nil {
506			return filepath.ToSlash(p)
507		}
508		return filepath.ToSlash(r)
509	}
510	
511	// dir judges the kustomization of one directory (a real path inside the limit)
512	// and, through it, everything it pulls in. A directory with none holds nothing
513	// to follow.
514	func (g *gate) dir(real string, depth int) gateVerdict {
515		if g.visited[real] || g.cache.has(real) {
516			return gateVerdict{}
517		}
518		g.visited[real] = true
519		where := gateSite{file: g.rel(real), dir: real, depth: depth}
520		switch {
521		case g.ctx.Err() != nil:
522			return where.unchecked("", "", "the check was cancelled")
523		case depth > g.lim.Depth:
524			return where.unchecked("", "", fmt.Sprintf("overlays are nested more than %d levels deep", g.lim.Depth))
525		}
526		file, v := g.kustomizationFile(real)
527		if file == "" {
528			return v
529		}
530		if g.count++; g.count > g.lim.Visited {
531			return where.unchecked("", "", fmt.Sprintf("more than %d kustomizations are pulled in", g.lim.Visited))
532		}
533		site := gateSite{file: g.rel(file), dir: real, depth: depth}
534		bases, v := g.kustomization(file, site)
535		if v.Kind != gateOK {
536			return v
537		}
538		// The kustomization is out of memory before its bases are read in turn.
539		for _, base := range bases {
540			if v := g.dir(base, depth+1); v.Kind != gateOK {
541				return v
542			}
543		}
544		return gateVerdict{}
545	}
546	
547	// kustomization judges the file of a kustomization. The directories it pulls in
548	// are returned, not read: this function's YAML is released first.
549	func (g *gate) kustomization(file string, site gateSite) ([]string, gateVerdict) {
550		// The kustomization file may itself be a link: what is read is what it names.
551		if target, err := filepath.EvalSymlinks(file); err != nil || !within(g.root, target) {
552			return nil, site.unchecked("", "", "the kustomization file leaves "+g.limit+" through a symbolic link")
553		}
554		node, reason := g.readYAML(file)
555		if reason == reasonNoDocument {
556			reason = "the kustomization file is empty"
557		}
558		if reason != "" {
559			return nil, site.unchecked("", "", reason)
560		}
561		g.bases = nil
562		v := g.applyMap(mapOf(kustomizationRules), node, "", site, true)
563		bases := g.bases
564		g.bases = nil
565		return bases, v
566	}
567	
568	// kustomizationFile is the kustomization file of dir, "" when there is none, or a
569	// verdict when there are several.
570	func (g *gate) kustomizationFile(dir string) (string, gateVerdict) {
571		var found []string
572		for _, name := range kustomizationNames {
573			p := filepath.Join(dir, name)
574			if _, err := os.Lstat(p); err == nil {
575				found = append(found, p)
576			} else if !isMissing(err) {
577				return "", gateSite{file: g.rel(p)}.unchecked("", "", "it cannot be read ("+errReason(err)+")")
578			}
579		}
580		switch len(found) {
581		case 0:
582			return "", gateVerdict{}
583		case 1:
584			return found[0], gateVerdict{}
585		}
586		return "", gateSite{file: g.rel(found[0])}.unchecked("", "", "the directory holds more than one kustomization file")
587	}
588	
589	// readYAML reads a file of the overlay, within what is left of the ceilings.
590	func (g *gate) readYAML(file string) (*yaml.Node, string) {
591		data, reason := readGateFile(file, min(g.lim.FileBytes, g.lim.TotalBytes-g.read))
592		if reason != "" {
593			return nil, reason
594		}
595		g.read += int64(len(data))
596		return parseGateYAML(data)
597	}
598	
599	// clipLen is how many characters of a name from the repository a message keeps.
600	const clipLen = 200
601	
602	// clip is s cut to clipLen characters, with an ellipsis when it was longer: a
603	// field, a reference or a kind is the repository's own text, of any length.
604	func clip(s string) string {
605		if utf8.RuneCountInString(s) <= clipLen {
606			return s
607		}
608		return string([]rune(s)[:clipLen]) + "…"
609	}
610	
611	func join(prefix, name string) string {
612		if prefix == "" {
613			return name
614		}
615		return prefix + "." + name
616	}
617	
618	func isNull(n *yaml.Node) bool { return n.Kind == yaml.ScalarNode && n.Tag == "!!null" }
619	
620	// apply judges the value n of field by r.
621	func (g *gate) apply(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
622		if isNull(n) || r.kind == gateData {
623			return gateVerdict{}
624		}
625		switch r.kind {
626		case gateList:
627			return g.applyList(r, n, field, s)
628		case gateMap:
629			return g.applyMap(r, n, field, s, false)
630		case gateNever:
631			return g.applyNever(n, field, s)
632		case gatePatch:
633			if n.Kind == yaml.MappingNode { // inline, as data; kustomize rejects it
634				return gateVerdict{}
635			}
636		}
637		if n.Kind != yaml.ScalarNode || n.Tag != "!!str" {
638			return s.unchecked(field, "", "a reference that is not a string")
639		}
640		return g.applyString(r.kind, n.Value, field, s)
641	}
642	
643	func (g *gate) applyList(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
644		if n.Kind != yaml.SequenceNode {
645			return s.unchecked(field, "", "a value that is not a list")
646		}
647		for i, e := range n.Content {
648			if v := g.apply(*r.elem, e, fmt.Sprintf("%s[%d]", field, i), s); v.Kind != gateOK {
649				return v
650			}
651		}
652		return gateVerdict{}
653	}
654	
655	// applyMap judges the entries of a mapping. closed is the kustomization itself,
656	// where a field that kustomizationRules does not list is refused; elsewhere an
657	// entry no rule lists holds no reference.
658	func (g *gate) applyMap(r gateRule, n *yaml.Node, field string, s gateSite, closed bool) gateVerdict {
659		if n.Kind != yaml.MappingNode {
660			return s.unchecked(field, "", "a value that is not a mapping")
661		}
662		for i := 0; i+1 < len(n.Content); i += 2 {
663			key := n.Content[i].Value
664			sub, known := lookupRule(r.fields, key)
665			if !known && closed {
666				return s.unchecked(join(field, key), "", "a field that kustomize v5.8.3 does not have")
667			}
668			if !known {
669				continue
670			}
671			if v := g.apply(sub, n.Content[i+1], join(field, key), s); v.Kind != gateOK {
672				return v
673			}
674		}
675		return gateVerdict{}
676	}
677	
678	// applyNever refuses any value of a field that names a program to run or its
679	// arguments.
680	func (g *gate) applyNever(n *yaml.Node, field string, s gateSite) gateVerdict {
681		var parts []string
682		if n.Kind == yaml.ScalarNode {
683			parts = append(parts, n.Value)
684		}
685		for _, c := range n.Content {
686			parts = append(parts, c.Value)
687		}
688		ref := strings.Join(parts, " ")
689		if ref == "" {
690			return gateVerdict{}
691		}
692		return s.remote(field, ref, "it names a program to run or arguments for it")
693	}
694	
695	func (g *gate) applyString(kind gateRuleKind, value, field string, s gateSite) gateVerdict {
696		switch kind {
697		case gateFileSource:
698			parts := strings.Split(value, "=")
699			if len(parts) > 2 {
700				return s.unchecked(field, value, "a files entry with more than one equal sign")
701			}
702			return g.reference(parts[len(parts)-1], false, field, s)
703		case gatePlugin:
704			if strings.Contains(value, "\n") {
705				return g.inlinePlugin(value, field, s)
706			}
707			return g.pluginPath(value, field, s)
708		case gatePatch:
709			if strings.Contains(value, "\n") {
710				if inlineResources(value) {
711					return gateVerdict{}
712				}
713				return s.unchecked(field, "", "text that is neither a path nor a patch")
714			}
715			return g.reference(value, false, field, s)
716		}
717		return g.reference(value, kind == gateBase, field, s)
718	}
719	
720	// inlineResources reports whether text is what kustomize reads as an inline
721	// patch: documents that are Kubernetes objects.
722	func inlineResources(text string) bool {
723		dec := yaml.NewDecoder(strings.NewReader(text))
724		found := false
725		for {
726			var doc yaml.Node
727			err := dec.Decode(&doc)
728			if errors.Is(err, io.EOF) {
729				return found
730			}
731			if err != nil || doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || !hasKey(doc.Content[0], "kind") {
732				return false
733			}
734			found = true
735		}
736	}
737	
738	// hasKey reports whether n is a mapping with a key of exactly this name.
739	func hasKey(n *yaml.Node, name string) bool {
740		return mapGet(n, name) != nil
741	}
742	
743	// mapGet is the value of the key spelled exactly name in the mapping n.
744	func mapGet(n *yaml.Node, name string) *yaml.Node {
745		if n == nil || n.Kind != yaml.MappingNode {
746			return nil
747		}
748		for i := 0; i+1 < len(n.Content); i += 2 {
749			if n.Content[i].Value == name {
750				return n.Content[i+1]
751			}
752		}
753		return nil
754	}
755	
756	// reference judges one reference: it must be local, and below the limit once
757	// symbolic links are resolved. A directory is noted to be read in turn when
758	// follow says so.
759	func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
760		real, found, v := g.resolve(ref, field, s)
761		if v.Kind != gateOK || !found {
762			return v
763		}
764		// Only a regular file or a directory: kustomize blocks on a pipe.
765		info, err := os.Stat(real)
766		switch {
767		case err != nil:
768			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
769		case info.IsDir():
770			if follow {
771				g.bases = append(g.bases, real)
772			}
773		case !info.Mode().IsRegular():
774			return s.unchecked(field, ref, "it is neither a regular file nor a directory")
775		}
776		return gateVerdict{}
777	}
778	
779	// resolve turns a reference of the kustomization at s.dir into a real path. found
780	// is false for a path that is not there: kustomize reports it and fetches nothing.
781	func (g *gate) resolve(ref, field string, s gateSite) (real string, found bool, v gateVerdict) {
782		if ref == "" {
783			return "", false, gateVerdict{} // the directory of the kustomization itself
784		}
785		if ok, reason := localRef(ref); !ok {
786			return "", false, s.remote(field, ref, reason)
787		}
788		cand := filepath.Join(s.dir, filepath.FromSlash(ref))
789		if !within(g.root, cand) {
790			return "", false, s.unchecked(field, ref, "it leaves "+g.limit)
791		}
792		real, err := filepath.EvalSymlinks(cand)
793		switch {
794		case isMissing(err):
795			return "", false, gateVerdict{}
796		case err != nil:
797			return "", false, s.unchecked(field, ref, "it cannot be resolved ("+errReason(err)+")")
798		case !within(g.root, real):
799			return "", false, s.unchecked(field, ref, "it leaves "+g.limit+" through a symbolic link")
800		}
801		return real, true, gateVerdict{}
802	}
803	
804	// pluginPath judges an entry of generators, transformers or validators that is
805	// not inline: a plugin configuration file. A directory is refused, not followed:
806	// kustomize reads the resources of its kustomization as plugin configurations
807	// (and runs what they say), where the gate reads them as resources.
808	func (g *gate) pluginPath(ref, field string, s gateSite) gateVerdict {
809		real, found, v := g.resolve(ref, field, s)
810		if v.Kind != gateOK || !found {
811			return v
812		}
813		info, err := os.Stat(real)
814		switch {
815		case err != nil:
816			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
817		case info.IsDir():
818			return s.unchecked(field, ref, "a plugin directory cannot be checked")
819		}
820		file := gateSite{file: g.rel(real), dir: s.dir, depth: s.depth}
821		node, reason := g.readYAML(real)
822		if reason != "" {
823			return file.unchecked("", "", reason)
824		}
825		return g.pluginConfig(node, "", file)
826	}
827	
828	// inlinePlugin judges a plugin configuration written in the kustomization.
829	func (g *gate) inlinePlugin(text, field string, s gateSite) gateVerdict {
830		node, reason := parseGateYAML([]byte(text))
831		if reason != "" {
832			return s.unchecked(field, "", "an inline plugin configuration: "+reason)
833		}
834		return g.pluginConfig(node, field, s)
835	}
836	
837	// pluginConfig judges the configuration of a plugin: a builtin one of a known
838	// kind, that runs no function, whose fields that name a file are local.
839	func (g *gate) pluginConfig(node *yaml.Node, prefix string, s gateSite) gateVerdict {
840		scalar := func(name string) string {
841			if n := mapGet(node, name); n != nil && n.Kind == yaml.ScalarNode && n.Tag == "!!str" {
842				return n.Value
843			}
844			return ""
845		}
846		if version := scalar("apiVersion"); version != "builtin" {
847			return s.unchecked(join(prefix, "apiVersion"), "", fmt.Sprintf("a plugin of apiVersion %q: only builtin plugins are read", clip(version)))
848		}
849		kind := scalar("kind")
850		fields, known := builtinPlugins[kind]
851		if !known {
852			return s.unchecked(join(prefix, "kind"), "", fmt.Sprintf("a builtin plugin of kind %q, which the gate does not know", clip(kind)))
853		}
854		if annotations := mapGet(mapGet(node, "metadata"), "annotations"); annotations != nil && annotations.Kind == yaml.MappingNode {
855			for i := 0; i+1 < len(annotations.Content); i += 2 {
856				for _, name := range functionAnnotations {
857					if strings.EqualFold(annotations.Content[i].Value, name) {
858						return s.unchecked(join(prefix, "metadata.annotations"), "", "a function annotation, which makes kustomize run a program")
859					}
860				}
861			}
862		}
863		return g.apply(mapOf(fields), node, prefix, s)
864	}
